package com.urlshortner.urls;

import com.urlshortner.InjectedRedirectFaultFilter;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;
import org.springframework.mock.web.MockServletContext;
import org.springframework.test.context.support.TestPropertySourceUtils;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;
import org.springframework.web.servlet.config.annotation.EnableWebMvc;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class CreationLimitHttpTest {
    private static final Instant NOW = Instant.parse("2026-01-01T00:00:00Z");
    private static final String URL = "https://example.com";
    private static final String BODY = "{\"url\":\"https://example.com\"}";

    @Configuration(proxyBeanMethods = false)
    @EnableWebMvc
    @Import({CreationLimitConfiguration.class, UrlErrors.class})
    static class WebConfig {
        @Bean UrlRepository repository() { return mock(UrlRepository.class); }
        @Bean CodeGenerator codes() { return mock(CodeGenerator.class); }
        @Bean UrlService service(UrlRepository repository, CodeGenerator codes) {
            return new UrlService(repository, codes, Clock.fixed(NOW, ZoneOffset.UTC), 30);
        }
        @Bean UrlController controller(UrlService service) {
            return new UrlController(service, "https://public.example/links/");
        }
    }

    private AnnotationConfigWebApplicationContext context(String property, CreationRateLimiter limiter) {
        var context = new AnnotationConfigWebApplicationContext();
        context.setServletContext(new MockServletContext());
        if (property != null) TestPropertySourceUtils.addInlinedPropertiesToEnvironment(context,
                "shortener.creation-limit-per-minute=" + property);
        if (limiter == null) {
            context.register(CreationRateLimiter.class);
        } else {
            // The refreshable context creates its BeanFactory during refresh.
            // Register before singleton construction, using that initialized factory.
            context.addBeanFactoryPostProcessor(factory ->
                    factory.registerSingleton("creationRateLimiter", limiter));
        }
        context.register(WebConfig.class);
        return context;
    }

    private MockMvc mvc(AnnotationConfigWebApplicationContext context) {
        return MockMvcBuilders.webAppContextSetup(context)
                .addFilters(new InjectedRedirectFaultFilter()).build();
    }

    @Test
    void registeredInterceptorUsesDefaultAndPropertyOverridesBeforeWrites() throws Exception {
        for (String property : new String[] {null, "1", "3"}) {
            try (var context = context(property, null)) {
                context.refresh();
                MockMvc mvc = mvc(context);
                var repository = context.getBean(UrlRepository.class);
                var codes = context.getBean(CodeGenerator.class);
                when(codes.next()).thenReturn("Ab12Cd34");
                when(repository.insert("Ab12Cd34", URL, null)).thenReturn(
                        new UrlRepository.StoredUrl("Ab12Cd34", URL, NOW, 0, null, null));
                int limit = property == null ? 20 : Integer.parseInt(property);
                for (int i = 0; i < limit; i++) {
                    mvc.perform(post("/app/api/urls").contextPath("/app")
                                    .header("Host", "caller" + i + ".example")
                                    .header("X-Forwarded-For", "192.0.2." + i)
                                    .contentType(MediaType.APPLICATION_JSON).content(BODY))
                            .andExpect(status().isCreated())
                            .andExpect(jsonPath("$.shortUrl").value("https://public.example/links/r/Ab12Cd34"));
                }
                clearInvocations(repository, codes);
                mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(BODY))
                        .andExpect(status().isTooManyRequests())
                        .andExpect(header().string("Retry-After", org.hamcrest.Matchers.matchesPattern("[1-9][0-9]*")))
                        .andExpect(header().doesNotExist("Location"))
                        .andExpect(content().json("{\"error\":\"Creation limit exceeded\"}"));
                verifyNoInteractions(repository, codes);
            }
        }
    }

    @Test
    void invalidConfigurationFailsContextInitialization() {
        for (String property : new String[] {"0", "-1", "nonnumeric"}) {
            try (var context = context(property, null)) {
                assertThrows(RuntimeException.class, context::refresh);
            }
        }
    }

    @Test
    void invalidAttemptsConsumeAllowanceAndRecoveryUsesMonotonicTime() throws Exception {
        AtomicLong time = new AtomicLong();
        try (var context = context(null, new CreationRateLimiter(3, time::get))) {
            context.refresh();
            MockMvc mvc = mvc(context);
            var repository = context.getBean(UrlRepository.class);
            var codes = context.getBean(CodeGenerator.class);
            for (String body : new String[] {"{", "{\"url\":42}",
                    "{\"url\":\"https://example.com\",\"expiresAt\":\"bad\"}"}) {
                mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                        .andExpect(status().isBadRequest());
            }
            mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content("{"))
                    .andExpect(status().isTooManyRequests()).andExpect(header().string("Retry-After", "60"));
            verifyNoInteractions(repository, codes);
            time.set(60_000_000_000L);
            mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content("{"))
                    .andExpect(status().isBadRequest()).andExpect(header().doesNotExist("Retry-After"));
        }
    }

    @Test
    void redirectsAndAnalyticsRemainUnlimitedAndDoNotConsumeAllowance() throws Exception {
        try (var context = context(null, new CreationRateLimiter(1, () -> 0L))) {
            context.refresh();
            MockMvc mvc = mvc(context);
            var repository = context.getBean(UrlRepository.class);
            when(repository.recordRedirect("valid", NOW)).thenReturn(Optional.of(URL));
            when(repository.find("valid")).thenReturn(Optional.of(
                    new UrlRepository.StoredUrl("valid", URL, NOW, 0, null, null)));
            when(repository.find("expired")).thenReturn(Optional.of(
                    new UrlRepository.StoredUrl("expired", URL, NOW, 0, null, NOW)));
            for (int phase = 0; phase < 2; phase++) {
                for (int i = 0; i < 25; i++) {
                    mvc.perform(get("/r/valid")).andExpect(status().isFound())
                            .andExpect(header().string("Location", URL))
                            .andExpect(header().doesNotExist("Retry-After"));
                    mvc.perform(get("/api/urls/valid/analytics")).andExpect(status().isOk())
                            .andExpect(jsonPath("$.clickCount").value(0))
                            .andExpect(header().doesNotExist("Retry-After"));
                }
                if (phase == 0) {
                    mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content("{"))
                            .andExpect(status().isBadRequest());
                }
            }
            mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(BODY))
                    .andExpect(status().isTooManyRequests());
            mvc.perform(get("/r/expired")).andExpect(status().isGone())
                    .andExpect(header().doesNotExist("Retry-After"));
            mvc.perform(get("/r/missing")).andExpect(status().isNotFound());
            mvc.perform(get("/api/urls/missing/analytics")).andExpect(status().isNotFound());
        }
    }
}

package com.urlshortner.urls;

import java.util.ArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class CreationRateLimiterTest {
    @Test
    void roundsRetryAndResetsAtExactBoundaryWithoutExtendingRejections() {
        AtomicLong time = new AtomicLong(-100);
        CreationRateLimiter limiter = new CreationRateLimiter(1, time::get);
        limiter.admit();
        assertEquals(60, rejected(limiter));
        time.incrementAndGet();
        assertEquals(60, rejected(limiter));
        time.set(-100 + 59_000_000_000L);
        assertEquals(1, rejected(limiter));
        time.set(-100 + 60_000_000_000L - 1);
        assertEquals(1, rejected(limiter));
        time.incrementAndGet();
        limiter.admit();
        assertEquals(60, rejected(limiter));
        time.addAndGet(600_000_000_000L);
        limiter.admit();
        assertEquals(60, rejected(limiter));
    }

    @Test
    void supportsNanoTimeWraparound() {
        AtomicLong time = new AtomicLong(Long.MAX_VALUE - 10);
        CreationRateLimiter limiter = new CreationRateLimiter(1, time::get);
        limiter.admit();
        time.addAndGet(60_000_000_000L);
        limiter.admit();
        assertEquals(60, rejected(limiter));
    }

    @Test
    void validatesConfigurationAndHonorsPositiveOverrides() {
        for (int invalid : new int[] {0, -1, Integer.MIN_VALUE}) {
            assertThrows(IllegalArgumentException.class, () -> new CreationRateLimiter(invalid));
        }
        for (int limit : new int[] {1, 3, 20}) {
            CreationRateLimiter limiter = new CreationRateLimiter(limit, () -> 0L);
            for (int i = 0; i < limit; i++) limiter.admit();
            assertEquals(60, rejected(limiter));
        }
    }

    @Test
    void admitsExactlyTwentyConcurrentAttemptsInEachWindow() throws Exception {
        AtomicLong time = new AtomicLong();
        CreationRateLimiter limiter = new CreationRateLimiter(20, time::get);
        var workers = Executors.newFixedThreadPool(16);
        try {
            for (int window = 0; window < 2; window++) {
                CountDownLatch start = new CountDownLatch(1);
                var results = new ArrayList<Future<Boolean>>();
                for (int i = 0; i < 100; i++) {
                    results.add(workers.submit(() -> {
                        if (!start.await(5, TimeUnit.SECONDS)) throw new AssertionError("Start timeout");
                        try {
                            limiter.admit();
                            return true;
                        } catch (CreationRateLimiter.LimitExceeded exception) {
                            assertEquals(60, exception.retryAfter());
                            return false;
                        }
                    }));
                }
                start.countDown();
                int admitted = 0;
                for (Future<Boolean> result : results) {
                    if (result.get(10, TimeUnit.SECONDS)) admitted++;
                }
                assertEquals(20, admitted);
                time.addAndGet(60_000_000_000L);
            }
        } finally {
            workers.shutdownNow();
            assertTrue(workers.awaitTermination(5, TimeUnit.SECONDS));
        }
    }

    private long rejected(CreationRateLimiter limiter) {
        return assertThrows(CreationRateLimiter.LimitExceeded.class, limiter::admit).retryAfter();
    }
}

package com.urlshortner.urls;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;

class DestinationTest {
    @ParameterizedTest
    @ValueSource(strings = {
            "http://example.com", "https://example.com:8443/a?x=1#part",
            "HTTPS://example.com/path%20name", "http://localhost:8080/", "https://[::1]/"
    })
    void acceptsHttpDestinations(String value) {
        assertTrue(Destination.valid(value));
    }

    @ParameterizedTest
    @NullAndEmptySource
    @ValueSource(strings = {
            " ", "/relative", "ftp://example.com", "https:///path", "https://",
            "https://user@example.com", "https://user:password@example.com",
            "https://example.com/\r", "https://example.com/\n", "https://example.com/\t",
            "https://example.com/\u0000", "https://example.com/%0d", "https://example.com/%0A",
            "https://example.com/%7f", "https://example.com/%ZZ", "https://example.com:abc/",
            "https://example.com:65536/", "https://example.com:/", " https://example.com",
            "https://example.com\\@evil.example/", "https://bad host/"
    })
    void rejectsInvalidDestinations(String value) {
        assertFalse(Destination.valid(value));
    }
}

package com.urlshortner.urls;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ExpiryCapTest {
    @ParameterizedTest
    @ValueSource(longs = {7, 30, 31, 365, Long.MAX_VALUE})
    void configuredLimitCannotExceedSevenDays(long configuredDays) {
        Instant now = Instant.parse("2026-01-01T00:00:00.123456789Z");
        UrlRepository repository = mock(UrlRepository.class);
        CodeGenerator codes = mock(CodeGenerator.class);
        UrlService service = new UrlService(repository, codes,
                Clock.fixed(now, ZoneOffset.UTC), configuredDays);
        String url = "https://example.com";
        Instant maximum = now.plus(Duration.ofDays(7));

        assertThrows(IllegalArgumentException.class, () -> service.create(url, maximum.plusNanos(1)));
        assertThrows(IllegalArgumentException.class,
                () -> service.create(url, now.plus(Duration.ofDays(30))));
        verifyNoInteractions(repository, codes);

        var saved = new UrlRepository.StoredUrl("Ab12Cd34", url, now, 0, null, maximum);
        when(codes.next()).thenReturn(saved.code());
        when(repository.insert(saved.code(), url, maximum)).thenReturn(saved);
        assertSame(saved, service.create(url, maximum));
        verify(repository).insert(saved.code(), url, maximum);
        verify(codes).next();
        verifyNoMoreInteractions(repository, codes);
    }

    @ParameterizedTest
    @ValueSource(longs = {0, -1, Long.MIN_VALUE})
    void rejectsNonpositiveConfiguration(long configuredDays) {
        assertThrows(IllegalArgumentException.class, () -> new UrlService(
                mock(UrlRepository.class), mock(CodeGenerator.class), Clock.systemUTC(), configuredDays));
    }
}

package com.urlshortner.urls;

import com.fasterxml.jackson.databind.SerializationFeature;
